-- A reading copy of the schema the migrations leave: generated by npm run db:schema, not to be run.

CREATE OR REPLACE FUNCTION public.study_day_of(p_user uuid, p_at timestamp with time zone)
 RETURNS date
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  zone text;
  rollover integer;
begin
  select p.time_zone, p.day_starts_at into zone, rollover
    from public.study_preferences p
   where p.user_id = p_user;
  rollover := coalesce(rollover, 4);
  begin
    return ((p_at at time zone coalesce(zone, 'America/Santiago')) - make_interval(hours => rollover))::date;
  exception when invalid_parameter_value then
    return ((p_at at time zone 'America/Santiago') - make_interval(hours => rollover))::date;
  end;
end;
$function$;

grant execute on function public.study_day_of(p_user uuid, p_at timestamp with time zone) to service_role;
